        int x = c ^ 48;
        while (isDigit(c = gc())) x = ((x + (x << 2)) << 1) + (c ^ 48);
        return f != 0 ? -x : x;
    }

    static boolean isDigit(int c) {
        return c >= '0' && c <= '9';
    }

    static void pc(char c) throws IOException {
        if (q1 == Len) {
            os.write(duf, 0, Len);
            q1 = 0;
        }
        duf[q1++] = (byte) c;
