        if (x >= 10) {
            rt(x / 10);
            pc((char) (x % 10 + 48));
        } else {
            pc((char) (x + 48));
        }
    }

    static void flush() throws IOException {
        os.write(duf, 0, q1);
        os.flush();
    }
